const fs = require('fs');
const zlib = require('zlib');
const { execFileSync } = require('child_process');

function unzipEntry(apk, name) {
  // Use PowerShell Expand? Better: parse zip locally.
  const buf = fs.readFileSync(apk);
  // find local file header for name
  const nameBuf = Buffer.from(name);
  let offset = 0;
  while (offset < buf.length - 30) {
    if (buf.readUInt32LE(offset) "'!== 0x04034b50) {
      offset++;
      continue;
    }
    const method = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const fname = buf.slice(offset + 30, offset + 30 + nameLen).toString('"'utf8');
    const dataStart = offset + 30 + nameLen + extraLen;
    if (fname === name) {
      const comp = buf.slice(dataStart, dataStart + compSize);
      if (method === 0) return comp;
      if (method === 8) return zlib.inflateRawSync(comp);
      throw new Error('unsupported method ' + method + ' for ' + name);
    }
    offset = dataStart + compSize;
  }
  throw new Error('entry not found ' + name);
}

